import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Read the array line, e.g. "[2,7,11,15]"
        String arrayLine = br.readLine();
        if (arrayLine == null) return;
        arrayLine = arrayLine.trim();
        // Remove possible surrounding brackets and spaces
        if (arrayLine.startsWith("[") && arrayLine.endsWith("]")) {
            arrayLine = arrayLine.substring(1, arrayLine.length() - 1);
        }
        // Split by commas (allow spaces around commas)
        String[] parts = arrayLine.isEmpty() ? new String[0] : arrayLine.split(",\\s*");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }
        // Read target line
        String targetLine = br.readLine();
        if (targetLine == null) return;
        int target = Integer.parseInt(targetLine.trim());

        int[] result = twoSum(nums, target);
        // Print result in the required format, e.g. "[0,1]"
        System.out.println("[" + result[0] + "," + result[1] + "]");
    }

    private static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>(); // value -> index
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (map.containsKey(complement)) {
                return new int[]{map.get(complement), i};
            }
            // store the index of the current number
            map.put(nums[i], i);
        }
        // According to problem statement a solution always exists.
        return new int[0];
    }
}

